(()=>{const known={omni:'omni',downloads:'downloads',files:'files','files-broker':'files','bloom-core':'bloom-core',core:'bloom-core',setup:'setup','master-control':'master-control'};window.obAppIcon=id=>{const img=document.createElement('img');img.className='app-icon';img.alt='';img.width=64;img.height=64;const key=known[id];img.src=key?'../shared/visual-icons/'+key+'.webp':'../shared/generic-app.svg';return img}})();